input.command:
cat > diagnosis.json <<'EOF'
{"spec_element": "invariant",
 "proof_obligation": "bridge",
 "diagnosis": "The only loop invariant is 2 <= i, which records nothing about the divisors already checked or the value of result. When the loop exits normally (i > n/2) with result = false (e.g. n = 4), Dafny cannot conclude that no k in [2, n) divides n, so the postcondition fails. The invariant must state that result is false and no k in [2, i) divides n, plus an upper bound on i; and the bridge needs the fact that any proper divisor k of n satisfies k <= n/2."}
EOF
cat > program.dfy <<'EOF'
lemma DivisorBound(n: int, k: int)
    requires n >= 2 && 2 <= k < n && n % k == 0
    ensures k <= n / 2
{
    var q := n / k;
    assert n == k * q;
    assert q >= 2;
}

method IsNonPrime(n: int) returns (result: bool)
    requires n >= 2
    ensures result <==> (exists k :: 2 <= k < n && n % k == 0)
{
    result := false;
    var i := 2;
    while i <= n/2
        invariant 2 <= i
        invariant !result
        invariant forall k :: 2 <= k < i ==> n % k != 0
    {
        if n % i == 0
        {
            result := true;
            break;
        }
        i := i + 1;
    }
    if !result {
        forall k | 2 <= k < n && n % k == 0
            ensures false
        {
            DivisorBound(n, k);
        }
    }
}
EOF
dafny verify program.dfy
